/** Why the room turned your camera off (since 1.12). moderator: an owner or admin did (voice.cameraOff); quota_exhausted: the quota brake; capability_disabled: the room's camera was turned off; not_allowed: you may no longer use a camera (role, guestsCanUseCamera); limit: the room's maxCameras went below the cameras on. */
export type CameraStopReason = (typeof CameraStopReason)[keyof typeof CameraStopReason];

export const RoomCloseReason = {
  Expired: "expired",
  EndedByOwner: "ended_by_owner",
  Archived: "archived",
  Deleted: "deleted",
  QuotaExhausted: "quota_exhausted",
  Suspended: "suspended",
} as const;
export type RoomCloseReason = (typeof RoomCloseReason)[keyof typeof RoomCloseReason];

/** User notices delivered by the UserHubDO; the web turns them into a sound and a toast. */
export const EventCode = {
  StreamStartedInRoom: "stream_started_in_room",
  ViewerJoinedYourStream: "viewer_joined_your_stream",
  YourStreamDropped: "your_stream_dropped",
  YourNetworkUnstable: "your_network_unstable",
  ChatMention: "chat_mention",
} as const;
/** User notices delivered by the UserHubDO; the web turns them into a sound and a toast. */
export type EventCode = (typeof EventCode)[keyof typeof EventCode];

/** Dotted lower camel case, e.g. slot.request. */
export type MessageTypeName = string;

/** Chosen by the sender of a request, echoed unchanged in the reply. */
export type MessageId = string;

export const DeviceOs = {
  Linux: "linux",
  Windows: "windows",
  Macos: "macos",
} as const;
export type DeviceOs = (typeof DeviceOs)[keyof typeof DeviceOs];

export const DeviceArch = {
  Amd64: "amd64",
  Arm64: "arm64",
} as const;
export type DeviceArch = (typeof DeviceArch)[keyof typeof DeviceArch];

/** Semantic version of the helper build. */
export type HelperVersion = string;

/** Pairing code the person types on /link: 6 characters from an alphabet without look-alikes, shown as XXX-XXX. Accepted in any case, with or without the hyphen. */
export type UserCode = string;

/** POST /api/devices/code (helper, no credentials). What the helper knows about itself; shown to the person who approves. */
export interface DeviceCodeRequest {
  /** Suggested device name, e.g. the host name. */
  name?: Label;
  os: DeviceOs;
  arch: DeviceArch;
  helperVersion: HelperVersion;
}

/** The pairing codes (RFC 8628 section 3.2, in milliseconds and camelCase). deviceCode is secret to the helper; userCode is shown to the person. */
export interface DeviceCodeResponse {
  deviceCode: string;
  userCode: UserCode;
  /** The /link page of this instance. */
  verificationUri: string;
  /** The /link page with the code filled in (/link?code=K7F-2QM): what the helper opens in the browser. */
  verificationUriComplete: string;
  expiresInMs: number;
  /** Wait at least this long between two polls of POST /api/devices/token. */
  intervalMs: number;
}

/** POST /api/devices/token (helper polls). */
export interface DeviceTokenRequest {
  deviceCode: string;
}

/** The device token, returned once. The helper keeps it in the OS keychain and sends it as Authorization: Bearer <deviceToken>. */
export interface DeviceTokenResponse {
  deviceId: Id;
  userId: Id;
  deviceToken: string;
}

/** GET /api/devices/code/:userCode (signed-in web user): what the helper sent, for the confirmation screen. */
export interface DeviceCodeInfo {
  userCode: UserCode;
  name?: Label;
  os: DeviceOs;
  arch: DeviceArch;
  helperVersion: HelperVersion;
  expiresAt: UnixMs;
}

/** POST /api/devices/approve (signed-in web user). os, arch and helperVersion default to what the helper sent with the code. */
export interface DeviceApproveRequest {
  userCode: UserCode;
  name: Label;
  os?: DeviceOs;
  arch?: DeviceArch;
  helperVersion?: HelperVersion;
}

/** A paired helper as Settings > Devices lists it. */
export interface Device {
  deviceId: Id;
  name: Label;
  os: DeviceOs;
  arch: DeviceArch;
  helperVersion: HelperVersion;
  createdAt: UnixMs;
  /** Last request made with the device token (updated at most every 5 minutes). Absent until first use. */
  lastSeenAt?: UnixMs;
}

export interface DeviceApproveResponse {
  userCode: UserCode;
}

/** GET /api/me/devices. */
export interface DeviceList {
  devices: Device[];
}

/** POST /api/app/authorize (signed-in browser session only): the person allowed the mobile app on the /app/authorize page. The fields are the page's query parameters (client, redirect_uri, code_challenge, code_challenge_method, state, device_name). */
export interface AppAuthorizeRequest {
  client: "openlive-mobile";
  redirectUri: "openlive://auth";
  /** BASE64URL(SHA-256(code_verifier)), RFC 7636. */
  codeChallenge: string;
  codeChallengeMethod: "S256";
  /** Opaque to the instance; returned unchanged in the redirect. */
  state: string;
  deviceName: string;
}

/** Where the page sends the browser: openlive://auth?code=…&state=…. The code is single use and expires in 2 minutes. */
export interface AppAuthorizeResponse {
  redirectTo: string;
}

/** POST /api/app/token (the app, no credentials): exchanges the code for an app token. client and redirectUri must be the ones the code was issued for. */
export interface AppTokenRequest {
  code: string;
  codeVerifier: string;
  client: string;
  redirectUri: string;
}

/** Who the app token signs in as. */
export interface AppUser {
  userId: Id;
  displayName: string;
  avatarUrl?: string;
}

/** The app token, returned once. The app keeps it in the Keychain or Keystore and sends it as Authorization: Bearer <token>. It works until revoked (Settings > Sessions, DELETE /api/app/token) or unused for 90 days. */
export interface AppTokenResponse {
  token: string;
  /** The token's id, as Settings > Sessions lists it. */
  tokenId: Id;
  user: AppUser;
}

/** POST /api/app/ws-ticket (app token): a single-use ticket for one WebSocket upgrade, sent as ?ticket=<ticket> on /ws/hub, /ws/spaces/:spaceId or /ws/rooms/:roomId. */
export interface AppWsTicketResponse {
  ticket: string;
  expiresAt: UnixMs;
}

/** The protocol versions the instance accepts: any minor of a major between min and max (docs/PROTOCOL.md 1). */
export interface ProtocolRange {
  min: ProtocolVersion;
  max: ProtocolVersion;
}

/** GET /.well-known/openlive.json (public, cacheable, no personal data): what the mobile app checks before connecting to an instance. */
export interface InstanceInfo {
  /** The instance's name: its host name until instances can be named. */
  name: string;
  iconUrl?: string;
  version: string;
  commit: string;
  protocol: ProtocolRange;
  /** What the instance offers: app_login (this login), ws_ticket, invite_deep_link, and capability:<stream|voice|camera|text> for each room capability the platform allows. Clients ignore names they do not know. */
  features: string[];
}

export const SdpType = {
  Offer: "offer",
  Answer: "answer",
} as const;
export type SdpType = (typeof SdpType)[keyof typeof SdpType];

/** An SDP offer or answer, as RTCSessionDescriptionInit. */
export interface SessionDescription {
  type: SdpType;
  sdp: string;
}

/** As RTCIceServer. TURN URLs on port 53 are already removed (browsers block that port). */
export interface IceServer {
  urls: string[];
  username?: string;
  credential?: string;
}

/** POST /api/rtc/rooms/:roomId/ice: short-lived STUN and TURN servers for this room. */
export interface IceServersResponse {
  iceServers: IceServer[];
}

/** A local track in the helper's offer. A simulcast video track is one track with its rids. */
export interface PublishTrack {
  mid: string;
  trackName: string;
  kind: TrackKind;
  /** Simulcast encodings, highest first (f, h, q). */
  rids?: string[];
  /** A video track's codec (since 1.14); absent means h264. The AV1 track is the top layer alone (no rids). */
  codec?: VideoCodec;
}

/** POST /api/rtc/rooms/:roomId/publish (helper, device token). */
export interface PublishRequest {
  sessionDescription: SessionDescription;
  tracks: PublishTrack[];
  preset: Preset;
  /** Highest bitrate the helper will send (all encodings and audio together). Refused above the room's maxBitrateKbps; also the meter's bitrate for the top layer. With an AV1 track (since 1.14) this is the H.264 track with the audio; the AV1 track sends about 65 % of its top layer on top, or as much in the quality mode (since 1.17, RoomSettings.av1QualityPresets; its viewers pull one of the two). */
  maxBitrateKbps: number;
}

export interface PublishedTrack {
  mid: string;
  trackName: string;
}

/** The SFU's answer to the helper's offer. Send stream.announce with sfuSessionId within announceWithinMs, or the publication is closed. */
export interface PublishResponse {
  sfuSessionId: Id;
  sessionDescription: SessionDescription;
  tracks: PublishedTrack[];
  announceWithinMs: number;
  /** Present when economy mode is on: fit the stream under it before announcing. */
  qualityCap?: QualityCap;
}

/** PUT /api/rtc/rooms/:roomId/publish/renegotiate (helper). */
export interface PublishRenegotiateRequest {
  sfuSessionId: Id;
  sessionDescription: SessionDescription;
}

/** POST /api/rtc/rooms/:roomId/unpublish (helper). Closes every track of the publication and ends its stream (ended_by_streamer). */
export interface UnpublishRequest {
  sfuSessionId: Id;
}

/** The SFU's reply to a renegotiation: an answer when an offer was sent, nothing when an answer was sent. */
export interface RenegotiateResponse {
  sessionDescription?: SessionDescription;
}

/** POST /api/rtc/rooms/:roomId/session (web). The viewer's one SFU session in this room, opened before any click. With an offer (a data channel is enough), the SFU answers it and DTLS connects with no media. */
export interface ViewerSessionRequest {
  sessionDescription?: SessionDescription;
}

export interface ViewerSessionResponse {
  sessionId: Id;
  iceServers: IceServer[];
  /** The SFU's answer, when the request carried an offer. */
  sessionDescription?: SessionDescription;
}

/** POST /api/rtc/rooms/:roomId/subscribe (web). Needs a slot held by the caller for that stream (slot.granted). */
export interface SubscribeRequest {
  sessionId: Id;
  slotId: Id;
  streamId: Id;
  /** Simulcast layer to start on; the highest when absent. */
  rid?: string;
  /** The video codec to pull (since 1.14): av1 when the viewer's browser decodes AV1. The stream's AV1 track (its top layer) is pulled only when it has one, the room allows AV1 for its preset and the pull starts on the top layer; otherwise, and when absent, the H.264 track. The response says which one. A viewer on AV1 that wants a lower layer pulls again (H.264); PUT .../layer only switches within the H.264 track. */
  codec?: VideoCodec;
}

export interface SubscribedTrack {
  mid: string;
  kind: TrackKind;
}

/** The pulled tracks on the viewer's session. With requiresImmediateRenegotiation, apply the SFU's offer and send the answer to PUT /api/rtc/rooms/:roomId/renegotiate. */
export interface SubscribeResponse {
  streamId: Id;
  requiresImmediateRenegotiation: boolean;
  sessionDescription?: SessionDescription;
  tracks: SubscribedTrack[];
  /** The simulcast layer requested; absent when the stream is not simulcast. */
  rid?: string;
  /** The codec of the pulled video track (since 1.14; absent from older servers: h264). */
  codec?: VideoCodec;
}

/** PUT /api/rtc/rooms/:roomId/renegotiate (web). */
export interface ViewerRenegotiateRequest {
  sessionId: Id;
  sessionDescription: SessionDescription;
}

/** PUT /api/rtc/rooms/:roomId/layer (web): switch the simulcast layer with tracks/update, no renegotiation. */
export interface LayerRequest {
  sessionId: Id;
  streamId: Id;
  rid: string;
}

/** POST /api/rtc/rooms/:roomId/unsubscribe (web): closes the stream's pulled tracks on the viewer's session. The slot stays until slot.release. */
export interface UnsubscribeRequest {
  sessionId: Id;
  streamId: Id;
}

/** POST /api/rtc/leave (web, sendBeacon on pagehide): closes every pulled track of the viewer's session and forgets it. */
export interface LeaveRequest {
  roomId: Id;
  sessionId: Id;
}

/** POST /api/metrics/viewer (web, since 1.7): one stream's playback numbers over the last window (about 30 s), aggregated from getStats() in the page. Ids only, no personal data. */
export interface ViewerMetricsRequest {
  roomId: Id;
  streamId: Id;
  windowMs: number;
  /** Time in the window with frames being presented. */
  watchMs: number;
  /** Click → first presented frame, sent once, in the window it happened. */
  ttffMs?: number;
  /** How this watch began: pulled on the click, or taken over from a hover pre-pull. */
  start: "click" | "prepull";
  /** The simulcast layer at the end of the window. */
  layer?: string;
  freezes: number;
  /** Mean decoded frames per second. */
  fps: number;
  /** Mean received bitrate. */
  bitrateKbps: number;
  lossPct: number;
  framesDropped: number;
  /** Media element errors and failed decodes. */
  decodeErrors: number;
  reconnects: number;
  /** Mean round-trip time to the SFU. */
  rttMs?: number;
  /** Mean jitter buffer delay. */
  jitterBufferMs?: number;
}

/** POST /api/rtc/rooms/:roomId/voice/publish (web, since 1.10): publish your microphone on your viewer session (POST .../session). The offer has every m-section of the session plus the new sendonly audio one; mid names it. Audio only: a mid that is not an audio m-section is refused. */
export interface VoicePublishRequest {
  sessionId: Id;
  sessionDescription: SessionDescription;
  mid: string;
}

/** The SFU's answer to the offer, and the published track's id as the others see it in voice.tracks. */
